lse, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "90214f2d-6527-3d38-7a92-62ee7f617e0c", "sort_order": 0, "title": "Statue Circle", "description": "Modern charm in historic city.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "dbaa7c09-b253-bb4f-3b32-556bb15177b4", "sort_order": 1, "title": "Birla Auditorium & Planetarium", "description": "Cultural and scientific marvels await.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "491c7c4a-fdac-2ce7-8795-bd03f46749d2", "sort_order": 2, "title": "Vidhan Sabha", "description": "Seat of Jaipur''s legislative power.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "21cd2c84-4e5d-9e7e-6c7a-82c8cc47927c", "sort_order": 3, "title": "Birla Mandir", "description": "Tranquil temple adorned with marble.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "dd19edf2-877b-1229-ccda-04d002d02192", "sort_order": 4, "title": "Jawahar Kala Kendra", "description": "Hub of Jaipur''s arts culture.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "b8548ca0-8c87-6118-7c3a-1dff21b34e37", "day_number": 2, "day_title": "Sightseeing in Jaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After a hearty breakfast, embark on a tour of Jaipur''s historic Pink City:\nIn the evening, enjoy the mesmerizing Light & Sound show at Amer Fort, a spectacular display of Rajasthan''s history through lights and sound.\nOvernight stay at a hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "fbf23d1b-9397-de9a-8fff-1073b412f250", "sort_order": 0, "title": "Hawa Mahal", "description": "Iconic palace of Jaipur''s winds.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "b4cf80eb-708e-e360-8624-15bddd005f2d", "sort_order": 1, "title": "City Palace", "description": "Royal heritage at its finest.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "c75e0675-197d-20d0-326a-29a7ff6a22dd", "sort_order": 2, "title": "Observatory / Jantar Mantar", "description": "Ancient marvels of celestial science.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "113dc641-b6c3-5274-e705-8a76070e0717", "sort_order": 3, "title": "Jal Mahal", "description": "Palace amidst Man Sagar Lake.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "a5324887-776c-14a4-a8be-c75b4d30c8dc", "sort_order": 4, "title": "Amer Fort", "description": "Majestic fortress overlooking Jaipur.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "b5a19c83-9354-a5ce-d12b-fed1ff04d31e", "sort_order": 5, "title": "Nahargarh Fort & Palace", "description": "Scenic fort with Jaipur views.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_t